 const live=node=>{audit(observer.takeRecords());try{return visit===v&&v.active&&v.bound===root&&v.work===work&&v.pending===pending&&v.request===request&&bytes([v.work,v.pending,v.request])===stateBytes&&ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true&&location.hash===route&&document.querySelector('[data-square-pens-root]')===root&&!invalid.has(root)&&!invalid.has(node)&&chains.get(node)?.every(([n,p])=>n.parentNode===p)&&root.contains(node)&&visible(node)&&!node.disabled;}catch{return false;}};
 const on=(node,type,fn,capture=false)=>{node.addEventListener(type,fn,capture);off.push(()=>node.removeEventListener(type,fn,capture));};
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 const redraw=(focus='#sp-task')=>{
  ctx.render?.();const nextRoot=document.querySelector('[data-square-pens-root]');let n=nextRoot?.querySelector(focus);
  if(n?.disabled){const action=n.dataset.spAction,other={move:'move-back','move-back':'move','reset-pieces':'move','why-next':'why-back','why-back':'why-next','a-less':'a-more','a-more':'a-less','b-less':'b-more','b-more':'b-less'}[action];n=other?nextRoot.querySelector(`[data-sp-action="${other}"]`):null;}
  if(!n||n.disabled||!visible(n))n=nextRoot?.querySelector('#sp-task,#square-pens-title');
  if(n){n.focus({preventScroll:true});const box=n.getBoundingClientRect();if(box.top<0||box.bottom>innerHeight)n.scrollIntoView({block:'nearest'});}
 };
 const propose=(next,focus)=>{if(!next)return;v.request=next;v.pending=null;v.ready=null;redraw(focus);};
